style.css:
@-moz-document domain("tiktok.com") {
/* Default: Make icons and general text pink */
  svg {
    fill: #ffcadd !important;
    color: #ffcadd !important;
  }

  h1, h2, h3, h4, h5, h6,
  p, span, div, a, li, label, strong, b {
    color: #ffcadd !important;
  }

  /* EXCEPTIONS (reset to original color): */

  /* Comments */
  [data-e2e="comment-list"] *,
  
  /* Usernames (often links to profiles) */
  a[data-e2e="browse-user-username"],
  span[data-e2e="browse-user-username"],

  /* Video descriptions (usually inside strong or p) */
  [data-e2e="browse-video-desc"] * {
    color: inherit !important;
    fill: inherit !important;
  }
}
